def find(P,Q):
    res=[]
    for ti in range(len(Q)-len(P)+1):
        for tj in range(len(Q[0])-len(P[0])+1):
            if all(Q[ti+a][tj+b]==P[a][b] for a in range(len(P)) for b in range(len(P[0]))) : res.append((ti,tj,'id'))
            if all(Q[len(P)-1-a][tj+b]==P[a][b] for a in range(len(P)) for b in range(len(P[0]))): res.append((ti,tj,'vflip'))
            if all(Q[ti+b][tj+len(P[0])-1-b]==P[a][b] for a in range(len(P)) for b in range(len(P[0]))): res.append((ti,tj,'hflip'))
