            if all(Q[len(Q)-1-ti-b][tj+a]==P[a][b] for a in range(len(P)) for b in range(len(P[0]))): res.append((ti,tj,'rot180'))
            if all(Q[len(Q)-1-ti-b][len(Q[0])-1-(tj+a)]==P[a][b] for a in range(len(P)) for b in range(len(P[0]))): res.append((ti,tj,'rot90?'))
