import os,re,json,numpy as np
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
from collections import defaultdict
def locs(A):
    z=[]
    for i in range(A.shape[0]):
        for j in range(A.shape[1]):
            if A[i,j]==0: z.append((i,j))
    return z
rs=lambda A:[p[0] for p in locs(A)]
cs=lambda A:[p[1] for p in locs(A)]
def f(I,crop=True):
    A=np.array(I); H,W=A.shape
    rs_=locs(A); r0=min(rs_); r1=max(rs_)
    cs_=locs(A); c0=min(cs_); c1=max(cs_)
    res=A.copy()
    for i in range(r1-r0+1):
        for j in range(c1-c0+1):
            res[r0+i,c0+j]=A[H-1-(r0+i),W-1-(c0+j)]
    if crop: return res[r0:r1+1,c0:c1+1].tolist()
    return res.tolist()
for name in ['Demo pair 4','Demo pair 5']:
    print(name,'cropmatch:',np.array_equal(np.array(f(G[name+' input'],True)),np.array(G[name+' output'])))
print(json.dumps(f(G['Test input'],True)))
